def merge_intervals(xs: list[list[int]]) -> list[list[int]]:
    result: list[list[int]] = []
    for start, end in sorted(([a, b] for a, b in xs), key=lambda p: p[0]):
        if result and start <= result[-1][1]:
            if end > result[-1][1]:
                result[-1][1] = end
        else:
            result.append([start, end])
    return result
